	private static final String NS = "urn:scan-backed-hash-build:";
	private static final IRI BUILD = iri("build");
	private static final IRI PROBE = iri("probe");
	private static final IRI SUBJECT_BUILD = iri("subject-build");
	private static final IRI SUBJECT_BUILD_SUBJECT = iri("subject-build-fixed");
	private static final IRI OBJECT_BUILD = iri("object-build");
	private static final IRI OBJECT_PROBE = iri("object-probe");
	private static final IRI OBJECT_BUILD_VALUE = iri("object-build-value");
