	private static final String OBJECT_CONSTANT_QUERY = "SELECT ?probe ?build WHERE { ?probe <" + OBJECT_PROBE
			+ "> ?build . ?build <" + OBJECT_BUILD + "> <" + OBJECT_BUILD_VALUE + "> }";
	private static final String FILTERED_EMPTY_QUERY = "SELECT ?probe ?build ?key WHERE { ?probe <" + PROBE
			+ "> ?key . ?build <" + BUILD + "> ?key . FILTER(?key >= 100000) }";

