		set(LmdbNativeJaninoCodegen.THRESHOLD_ROWS_PROPERTY, "0");
		set(LmdbNativeKernelInterpreter.ENABLED_PROPERTY, "true");
		set(LmdbNativeKernelLowering.HASH_JOIN_PROPERTY, "true");
