	private void assertDuplicateHashBuildBoundary(String route, boolean oneBeyondCap) throws Exception {
		replaceBuildRowsWithDuplicateKeys(BOUNDARY_CAP / 2);
		set(NATIVE, "true");
		Optimized optimized = optimizeAndRun(QUERY, route, "probe", "build", "key");
		assertThat(optimized.bag()).isNotEmpty();
		if (oneBeyondCap) {
			appendDuplicateBuildKey(0);
		}
		Map<List<Value>, Integer> expected = bag(memoryRepository, QUERY, "probe", "build", "key");
		set(NATIVE, "false");
		assertThat(bag(repository, QUERY, "probe", "build", "key")).isEqualTo(expected);
		set(NATIVE, "true");
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			CountedSource counted = new CountedSource((NativeLmdbQuerySource) dataset);
			NativeRowsStep step = compileCountedStep(optimized, route, dataset, counted);
			assertThat(step.arg).isInstanceOf(MultiJoinPlan.class);
			RowState row = new RowState(step.source, step.layout, EmptyBindingSet.getInstance());
			try {
				assertThat(LmdbNativeAggregateCompiler.initializeRow(row, row.base, row.source, row.layout)).isTrue();
				MultiJoinPlan plan = (MultiJoinPlan) step.arg;
				LmdbNativeHashJoin.KernelHashPlan preferred = LmdbNativeKernelLowering.preferredRowHashPlan(plan, row);
				assertThat(preferred).as("statistics select the real duplicate-key hash plan").isNotNull();
				assertThat(preferred.build.p.constant).isEqualTo(row.source.idOf(BUILD));
				LmdbNativeKernelLowering.Lowered lowered = LmdbNativeKernelLowering
						.lowerRows(step.arg, row, optimized.expression(), true);
				assertThat(lowered).isNotNull();
				LmdbNativeKernelIr.HashBuild build = nodes(lowered).stream()
						.filter(LmdbNativeKernelIr.HashBuild.class::isInstance)
						.map(LmdbNativeKernelIr.HashBuild.class::cast)
						.findFirst()
						.orElseThrow();
				assertThat(build.maxRows).isEqualTo(BOUNDARY_CAP);
				assertThat(build.pipeline).anyMatch(LmdbNativeKernelIr.ScanQuad.class::isInstance);
			} finally {
				row.memoryScope.close();
			}

			Map<List<Value>, Integer> actual = evaluate(step, route, "probe", "build", "key");
			assertThat(actual).as(oneBeyondCap ? "cap+1 refusal retains duplicate-key bag" : "exact-cap build succeeds")
					.isEqualTo(expected);
			assertThat(counted.scanCloses).as("exact-cap and refused-cap paths close every scan")
					.isEqualTo(counted.scanOpens);
			assertThat(counted.scanOpens).isPositive();
		}
	}

